public class Solution {
    public static String mystery(int n) {
        String out = "";
        for (int i = 1; i <= n; i++) {
            if (i % 3 == 0) {
                out += "#";
            } else if (i % 2 == 0) {
                out += ".";
            } else {
                out += "o";
            }
        }
        return out;
    }
}

